public interface FileSystemItem {
    long calculateSizeInBytes();
}

public class DirectoryComposite implements FileSystemItem {
    private List<FileSystemItem> children;

    public long calculateSizeInBytes() {
        return children.stream().mapToLong(FileSystemItem::calculateSizeInBytes).sum();
    }
}
